    "deepdive_kicker": "Com funciona",
    "deepdive_title": "Com funciona XowApp, pas a pas",
    "deepdive_intro": "L'Ana vol ensenyar les seves fotos a en Carlos sense que ell se'n quedi una còpia. Així és com ho fan, i per què és segur.",
    "usecases_kicker": "Pas a pas",
    "usecases_title": "Com es viu l'experiència a XowApp",
    "characters_title": "L'Anna i en Carles et mostren com funciona",
    "char_woman_name": "Anna",
