    "profile_delete_modal_cancel": "Cancel·lar",
    "profile_delete_modal_confirm_button": "Eliminar el meu compte permanentment",
    "profile_delete_error_generic": "Error en eliminar el compte. Si us plau, torneu-ho a provar.",
