    "deepdive_kicker": "Como funciona",
    "deepdive_title": "Como funciona o XowApp, passo a passo",
    "deepdive_intro": "Ana quer mostrar suas fotos para Carlos sem que ele fique com uma cópia. É assim que eles fazem, e é por isso que é seguro.",
    "usecases_kicker": "Passo a passo",
    "usecases_title": "A experiência XowApp na prática",
    "characters_title": "Ana e Carlos mostram como funciona",
    "char_woman_name": "Ana",
    "char_woman_role": "Mostra suas fotos a partir do celular dela",
